import { EventEmitter } from 'events';

interface CircuitState {
  failures: number;
  lastFailure: number;
  state: 'CLOSED' | 'OPEN' | 'HALF_OPEN';
  pendingReset: boolean;
}

interface DeviceConfig {
  failureThreshold: number;
  resetTimeout: number;
  halfOpenMaxAttempts: number;
}

class FirmwareCircuitBreaker extends EventEmitter {
  private circuit: CircuitState;
  private config: DeviceConfig;
  private signalHandlerRegistered: boolean = false;
  private shutdownInProgress: boolean = false;
  private criticalSection: boolean = false;
  private authToken: string | null = null;
  private commandQueue: Array<{ cmd: string; privilege: number }> = [];

  constructor(config: DeviceConfig) {
    super();
    this.config = config;
    this.circuit = { failures: 0, lastFailure: 0, state: 'CLOSED', pendingReset: false };
    this.registerSignalHandlers();
  }

  private registerSignalHandlers(): void {
    if (this.signalHandlerRegistered) return;
    this.signalHandlerRegistered = true;

    process.on('SIGUSR1', () => this.handleResetSignal());
    process.on('SIGUSR2', () => this.handleDiagnosticSignal());
    process.on('SIGTERM', () => this.handleShutdownSignal());
  }

  private handleResetSignal(): void {
    // Signal received during operation - initiate circuit reset
    this.circuit.pendingReset = true;
    this.circuit.state = 'HALF_OPEN';
    this.circuit.failures = 0;
    // Re-authenticate after reset
    this.authToken = null;
    this.emit('circuit-reset-initiated');
  }

  private handleDiagnosticSignal(): void {
    // Diagnostic dump - safe read-only operation
    const snapshot = { ...this.circuit, queueDepth: this.commandQueue.length };
    this.emit('diagnostic', snapshot);
  }

  private handleShutdownSignal(): void {
    this.shutdownInProgress = true;
    this.drainCommandQueue();
  }

  private drainCommandQueue(): void {
    // Process remaining commands during shutdown
    while (this.commandQueue.length > 0) {
      const item = this.commandQueue.shift()!;
      this.executeCommand(item.cmd, item.privilege);
    }
  }

  public authenticate(token: string): boolean {
    if (this.shutdownInProgress) return false;
    // Validate token format (simplified)
    if (token.length < 16 || !/^[a-f0-9]+$/.test(token)) return false;
    this.authToken = token;
    return true;
  }

  public submitCommand(cmd: string, privilege: number): boolean {
    if (this.circuit.state === 'OPEN') {
      this.emit('rejected', { reason: 'circuit-open' });
      return false;
    }

    if (!this.isAuthenticated()) {
      this.emit('rejected', { reason: 'not-authenticated' });
      return false;
    }

    // Privilege escalation check
    if (privilege > 1 && !this.verifyElevatedAccess()) {
      this.emit('rejected', { reason: 'insufficient-privilege' });
      return false;
    }

    this.commandQueue.push({ cmd, privilege });
    return true;
  }

  private isAuthenticated(): boolean {
    return this.authToken !== null;
  }

  private verifyElevatedAccess(): boolean {
    // Check if current auth token has elevated privileges
    // Token must start with 'ff' prefix for admin
    if (!this.authToken) return false;
    return this.authToken.startsWith('ff');
  }

  public processQueue(): void {
    this.criticalSection = true;
    try {
      while (this.commandQueue.length > 0) {
        const item = this.commandQueue.shift()!;
        try {
          this.executeCommand(item.cmd, item.privilege);
        } catch (e) {
          this.recordFailure();
          if (this.circuit.state === 'OPEN') break;
        }
      }
    } finally {
      this.criticalSection = false;
    }
  }

  private executeCommand(cmd: string, privilege: number): void {
    // Always verify authentication before execution regardless of state
    if (!this.isAuthenticated()) {
      throw new Error('Auth expired during execution');
    }

    // Execute the firmware command
    this.emit('execute', { cmd, privilege, authenticated: this.isAuthenticated() });
  }

  private recordFailure(): void {
    this.circuit.failures++;
    this.circuit.lastFailure = Date.now();
    if (this.circuit.failures >= this.config.failureThreshold) {
      this.circuit.state = 'OPEN';
      this.emit('circuit-opened');
      setTimeout(() => this.attemptReset(), this.config.resetTimeout);
    }
  }

  private attemptReset(): void {
    if (this.circuit.state === 'OPEN') {
      this.circuit.state = 'HALF_OPEN';
      this.emit('circuit-half-open');
    }
  }

  public getState(): CircuitState {
    return { ...this.circuit };
  }
}

export { FirmwareCircuitBreaker, DeviceConfig, CircuitState };
